// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        address actor,
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 seqNumber,
        bytes32 batcherHash,
        uint256 overhead,
        uint256 scalar
    ) public {
        // depositorAccount() is the zero address (never set), so only address(0)
        // can pass the require; force msg.sender to it so the call succeeds in
        // both the reference and the mutant.
        vm.prank(address(0));
        c.setL1BlockValues(number, timestamp, basefee, hash, seqNumber, batcherHash, overhead, scalar);

        // General rule: setL1BlockValues never mutates state, so the stored
        // sequence number always remains 0, regardless of the argument supplied.
        assertTrue(c.sequenceNumber() == 0);
    }
}
